using namespace web; using namespace web::physics;
namespace {
void check(bool v,const char* message){if(!v)throw std::runtime_error(message);}
void near(V3 a,V3 b,double tolerance,const char* message){check(length(a-b)<=tolerance,message);}
Graph fixture(){Graph g;for(V2 uv:{V2{0,0},V2{1,0},V2{1,1},V2{0,1},V2{.4,.3},V2{.2,.7},V2{.6,.5},V2{.7,.75}}){Particle p;p.id=int(g.particles.size());p.uv=uv;p.x=p.rest={uv.x,uv.y,0};g.particles.push_back(p);}for(auto ab:{std::array<int,2>{0,1},{1,2},{2,3},{3,0},{0,4},{4,6},{6,2},{4,5},{5,7}}){Edge e;e.id=int(g.edges.size());e.a=ab[0];e.b=ab[1];g.edges.push_back(e);}g.particles[0].anchor=17;g.particles[0].invMass=0;return g;}
long double orient(V2 a,V2 b,V2 c){return (long double)(b.x-a.x)*(c.y-a.y)-(long double)(b.y-a.y)*(c.x-a.x);}
bool crosses(V2 a,V2 b,V2 c,V2 d){return orient(a,b,c)*orient(a,b,d)<-1e-28L&&orient(c,d,a)*orient(c,d,b)<-1e-28L;}
std::pair<int,int> key(int a,int b){return std::minmax(a,b);}
void topology(const RestCage&c,const Graph&g){std::set<int> seen;std::set<std::pair<int,int>> edges;double area=0;for(auto t:c.triangles()){check(orient(c.uv()[t[0]],c.uv()[t[1]],c.uv()[t[2]])>0,"positive UV triangle");area+=double(orient(c.uv()[t[0]],c.uv()[t[1]],c.uv()[t[2]]))/2;for(int k=0;k<3;++k){seen.insert(t[k]);edges.insert(key(t[k],t[(k+1)%3]));}}check(seen.size()==g.particles.size(),"every particle represented by a triangle");for(auto constraint:c.constraints())check(edges.count(key(constraint.particles[0],constraint.particles[1]))==1,"constraint recovered as mesh edge");for(auto ab:edges)for(auto e:g.edges)check(!crosses(c.uv()[ab.first],c.uv()[ab.second],g.particles[e.a].uv,g.particles[e.b].uv),"triangle edge must not cross source constraint");check(std::abs(area-1)<1e-10,"triangles cover square hull exactly");}
void constrainedQuality(const RestCage&c){std::map<std::pair<int,int>,std::vector<int>> adjacent;std::set<std::pair<int,int>> protectedEdges;for(auto e:c.constraints())protectedEdges.insert(key(e.particles[0],e.particles[1]));for(int f=0;f<int(c.triangles().size());++f)for(int k=0;k<3;++k)adjacent[key(c.triangles()[f][k],c.triangles()[f][(k+1)%3])].push_back(f);for(auto [edge,faces]:adjacent)if(faces.size()==2&&!protectedEdges.count(edge)){auto t=c.triangles()[faces[0]];int opposite=-1,other=-1;for(int v:t)if(v!=edge.first&&v!=edge.second)opposite=v;for(int v:c.triangles()[faces[1]])if(v!=edge.first&&v!=edge.second)other=v;if(!crosses(c.uv()[edge.first],c.uv()[edge.second],c.uv()[opposite],c.uv()[other]))continue;V2 p=c.uv()[other],a=c.uv()[t[0]],b=c.uv()[t[1]],d=c.uv()[t[2]];long double ax=(long double)a.x-p.x,ay=(long double)a.y-p.y,bx=(long double)b.x-p.x,by=(long double)b.y-p.y,cx=(long double)d.x-p.x,cy=(long double)d.y-p.y;long double al=ax*ax+ay*ay,bl=bx*bx+by*by,cl=cx*cx+cy*cy,det=al*(bx*cy-by*cx)-bl*(ax*cy-ay*cx)+cl*(ax*by-ay*bx),scale=al*(std::abs(bx*cy)+std::abs(by*cx))+bl*(std::abs(ax*cy)+std::abs(ay*cx))+cl*(std::abs(ax*by)+std::abs(ay*bx));check(det<=256*std::numeric_limits<long double>::epsilon()*scale,"non-source diagonals locally Delaunay after constraint recovery");}}
void affineAndRigid(){auto g=fixture();auto c=buildRestCage(g);topology(c,g);check(c.triangles()==buildRestCage(g).triangles(),"deterministic triangle indices");auto affine=[](V3 p){return V3{2*p.x+.3*p.y+1,-.4*p.x+1.1*p.y-2,.2*p.x+.5*p.y+3};};for(auto&p:g.particles)p.x=affine(p.rest);for(int j=0;j<=20;++j)for(int i=0;i<=20;++i){V2 uv{i/20.,j/20.};auto b=bindCageUV(c,uv);check(bool(b),"square UV covered");near(evaluateCage(c,*b,g),affine({uv.x,uv.y,0}),1e-11,"affine reproduction exact");}
auto rigid=[](V3 p){const double co=std::cos(.73),si=std::sin(.73);return V3{co*p.x+si*p.z+2,p.y-3,-si*p.x+co*p.z+1};};for(auto&p:g.particles)p.x=rigid(p.rest);for(auto t:c.triangles()){V2 uv=(c.uv()[t[0]]+c.uv()[t[1]]+c.uv()[t[2]])*(1./3);V3 rest{uv.x,uv.y,.13};auto b=bindCageUV(c,uv,rest,nullptr,CageOffsetMode::TriangleFrame);near(cageRestPosition(c,*b),rest,1e-12,"carrier rest offset reproduces rest shape");near(evaluateCage(c,*b,g),rigid(rest),1e-11,"rigid reproduction rotates rest offset");}
for(auto&p:g.particles)if(p.anchor>=0){p.x=p.rest;auto b=bindCageUV(c,p.uv);near(evaluateCage(c,*b,g),p.rest,0,"anchors exactly fixed");}
check(!bindCageUV(c,{2,.5}),"outside hull rejected");}
void edgeContinuityAndOwnership(){auto g=fixture();auto c=buildRestCage(g);std::map<std::pair<int,int>,std::vector<int>> adjacent;for(int f=0;f<int(c.triangles().size());++f)for(int k=0;k<3;++k)adjacent[key(c.triangles()[f][k],c.triangles()[f][(k+1)%3])].push_back(f);for(auto&p:g.particles)p.x=p.rest+V3{.01*std::sin(p.id),.02*std::cos(p.id),.1*std::sin(.7*p.id)};for(auto [ab,faces]:adjacent)if(faces.size()==2){V2 uv=c.uv()[ab.first]*.37+c.uv()[ab.second]*.63;auto a=bindCageTriangle(c,faces[0],uv),b=bindCageTriangle(c,faces[1],uv);check(a&&b,"both incident faces accept shared edge");near(evaluateCage(c,*a,g),evaluateCage(c,*b,g),1e-12,"shared cage edge continuous");}
std::vector<unsigned char> mask(c.triangles().size(),0);check(!bindCageUV(c,{.5,.5},std::nullopt,&mask),"caller can disable all faces");for(int f=0;f<int(c.triangles().size());++f)check(cageTriangleComponent(c,f,g)==0,"single component face ownership");g.particles[0].component=9;bool mixed=false;for(int f=0;f<int(c.triangles().size());++f)mixed|=cageTriangleComponent(c,f,g)==-1;check(mixed,"mixed-component triangles identified");}
void curvedEdgeContinuity(){auto g=fixture();for(auto&p:g.particles)p.x=p.rest={p.uv.x,p.uv.y,.2*p.uv.x*p.uv.y};const auto c=buildRestCage(g);std::map<std::pair<int,int>,std::vector<int>> adjacent;for(int f=0;f<int(c.triangles().size());++f)for(int k=0;k<3;++k)adjacent[key(c.triangles()[f][k],c.triangles()[f][(k+1)%3])].push_back(f);for(auto&p:g.particles)p.x=p.rest+V3{.01*std::sin(p.id),.02*std::cos(p.id),.1*std::sin(.7*p.id)};for(auto [ab,faces]:adjacent)if(faces.size()==2){V2 uv=c.uv()[ab.first]*.37+c.uv()[ab.second]*.63;V3 rest{uv.x,uv.y,.2*uv.x*uv.y};auto a=bindCageTriangle(c,faces[0],uv,rest),b=bindCageTriangle(c,faces[1],uv,rest);check(a&&b,"curved shared edge bindings");near(evaluateCage(c,*a,g),evaluateCage(c,*b,g),1e-12,"analytic carrier remains continuous across cage edges under nonrigid motion");}}
void collinearAndErrors(){auto g=fixture();g.edges.clear();for(auto ab:{std::array<int,2>{0,2},{0,2}}){Edge e;e.id=int(g.edges.size());e.a=ab[0];e.b=ab[1];g.edges.push_back(e);}auto c=buildRestCage(g);topology(c,g);check(c.constraints().size()==1&&c.constraints()[0].sourceEdges.size()==2,"parallel physical edges dedup geometric constraint with provenance");Particle p;p.id=int(g.particles.size());p.uv={.5,.5};p.rest=p.x={.5,.5,0};g.particles.push_back(p);c=buildRestCage(g);topology(c,g);check(c.constraints().size()==2,"constraint split at collinear graph particle");bool rejected=false;try{buildRestCage(g,{1,25200});}catch(const std::exception&){rejected=true;}check(rejected,"face budget rejects");rejected=false;try{buildRestCage(g,{8400,3});}catch(const std::exception&){rejected=true;}check(rejected,"vertex budget rejects");Edge crossing;crossing.a=1;crossing.b=3;g.edges.push_back(crossing); // Both segments pass through particle 8, so this is planar.
c=buildRestCage(g);topology(c,g);g.particles.pop_back();rejected=false;try{buildRestCage(g);}catch(const std::exception&){rejected=true;}check(rejected,"unjoined crossing rejects");g=fixture();g.particles.push_back(g.particles[0]);rejected=false;try{buildRestCage(g);}catch(const std::exception&){rejected=true;}check(rejected,"duplicate UV particles reject rather than lose a physical node");}
void nearBoundaryHull(){Graph g;for(V2 uv:{V2{0,0},V2{1,0},V2{1,1},V2{0,1},V2{.999,.35}}){Particle p;p.uv=uv;p.x=p.rest={uv.x,uv.y,0};g.particles.push_back(p);}auto c=buildRestCage(g);check(c.triangles().size()==4&&bindCageUV(c,{.9995,.35}),"near-boundary particle preserves entire convex hull");for(auto ab:{std::array<int,2>{0,1},{1,2},{2,3},{3,0}}){Edge e;e.a=ab[0];e.b=ab[1];g.edges.push_back(e);}c=buildRestCage(g);topology(c,g);}
void gridConstraintCavity(){Graph g;for(V2 uv:{V2{1./7,2./7},V2{2./7,3./7},V2{1./7,1./7},V2{3./7,0},V2{4./7,2./7},V2{3./7,1./7},V2{1,0}}){Particle p;p.uv=uv;p.x=p.rest={uv.x,uv.y,0};g.particles.push_back(p);}Edge e;e.a=0;e.b=6;g.edges.push_back(e);auto c=buildRestCage(g);check(!c.triangles().empty(),"near-collinear grid cavity triangulates");std::set<int> seen;for(auto t:c.triangles())for(int i:t)seen.insert(i);check(seen.size()==g.particles.size(),"grid cavity retains all nodes");}
void cocircularGrid(){std::mt19937 random(420);for(int run=0;run<4;++run){std::vector<V2> points;for(int x=0;x<8;++x)for(int y=0;y<8;++y)points.push_back({x/7.,y/7.});std::shuffle(points.begin(),points.end(),random);Graph g;for(auto uv:points){Particle p;p.uv=uv;p.rest=p.x={uv.x,uv.y,0};g.particles.push_back(p);}auto c=buildRestCage(g);topology(c,g);check(c.triangles()==buildRestCage(g).triangles(),"cocircular grid deterministic and convergent");}}
void enclosedCavityNode(){Graph g;for(V2 uv:{V2{0.98232035359292813,0.062758744825103505},V2{0.85759284814303716,0.15590688186236276},V2{0.77213455730885383,0.15252694946101078},V2{0.5712585748285034,0.25569488610227797},V2{0.95283094338113239,0.06950860982780345},V2{0.86934261314773709,0.18641627167456651}}){Particle p;p.uv=uv;p.rest=p.x={uv.x,uv.y,0};g.particles.push_back(p);}Edge e;e.a=0;e.b=3;g.edges.push_back(e);auto c=buildRestCage(g);std::set<int> seen;for(auto t:c.triangles())for(int i:t)seen.insert(i);check(seen.size()==g.particles.size(),"constraint cavity preserves enclosed physical particle");}
void skinnyOffsetFrame(){Graph g;for(V2 uv:{V2{0,0},V2{1,0},V2{0,1}}){Particle p;p.uv=uv;g.particles.push_back(p);}g.particles[0].rest=g.particles[0].x={0,0,0};g.particles[1].rest=g.particles[1].x={1,0,0};g.particles[2].rest=g.particles[2].x={1,1e-8,0};auto c=buildRestCage(g);V3 carrier{2./3+.1,1e-8/3+.2,.3};auto b=bindCageUV(c,{1./3,1./3},carrier,nullptr,CageOffsetMode::TriangleFrame);check(bool(b),"skinny offset frame binds");near(cageRestPosition(c,*b),carrier,1e-12,"skinny frame preserves tangential carrier offset");}
void invalidInputs(){auto g=fixture();bool failed=false;try{buildRestCage(g,{8401,25200});}catch(const std::exception&){failed=true;}check(failed,"hard face budget cannot be raised");auto c=buildRestCage(g);failed=false;try{bindCageTriangle(c,0,{.2,.2},std::nullopt,static_cast<CageOffsetMode>(99));}catch(const std::exception&){failed=true;}check(failed,"unknown rest offset mode rejected");failed=false;try{bindCageUV(c,{std::numeric_limits<double>::quiet_NaN(),0});}catch(const std::exception&){failed=true;}check(failed,"nonfinite query rejected");std::vector<unsigned char> mask;failed=false;try{bindCageUV(c,{.2,.2},std::nullopt,&mask);}catch(const std::exception&){failed=true;}check(failed,"wrong face mask rejected");auto b=*bindCageUV(c,{.2,.2});b.barycentric={1,1,1};failed=false;try{evaluateCage(c,b,g);}catch(const std::exception&){failed=true;}check(failed,"invalid externally edited binding rejected");g.particles[1].uv.x=std::numeric_limits<double>::infinity();failed=false;try{buildRestCage(g);}catch(const std::exception&){failed=true;}check(failed,"nonfinite rest UV rejected");}
void reportDeformation(const RestCage&c,const Graph&g,const char*label,unsigned seed){std::map<std::pair<int,int>,std::vector<int>> adjacent;std::vector<V3> normals;int inverted=0,collapsed=0;double displacement=0;for(int f=0;f<int(c.triangles().size());++f){auto t=c.triangles()[f];V3 now=cross(g.particles[t[1]].x-g.particles[t[0]].x,g.particles[t[2]].x-g.particles[t[0]].x),rest=cross(c.rest()[t[1]]-c.rest()[t[0]],c.rest()[t[2]]-c.rest()[t[0]]);normals.push_back(now);inverted+=now.x*rest.x+now.y*rest.y+now.z*rest.z<0;collapsed+=length(now)<1e-12;for(int k=0;k<3;++k)adjacent[key(t[k],t[(k+1)%3])].push_back(f);}int folds=0;for(auto [edge,faces]:adjacent)if(faces.size()==2){V3 a=normals[faces[0]],b=normals[faces[1]];bool folded=a.x*b.x+a.y*b.y+a.z*b.z<0;folds+=folded;if(folded&&g.tick==0){bool protectedEdge=false;for(auto constraint:c.constraints())protectedEdge|=key(constraint.particles[0],constraint.particles[1])==edge;std::cout<<"DIAGNOSTIC rest_fold seed="<<seed<<" particles="<<edge.first<<','<<edge.second<<" faces="<<faces[0]<<','<<faces[1]<<" source_constraint="<<protectedEdge<<'\n';}}for(auto&p:g.particles)displacement=std::max(displacement,length(p.x-p.rest));std::cout<<"DIAGNOSTIC "<<label<<" seed="<<seed<<" ticks="<<g.tick<<" inverted_vs_rest="<<inverted<<" adjacent_over90="<<folds<<" collapsed_area2_lt1e-12="<<collapsed<<" max_displacement="<<displacement<<" breaks="<<g.events.size()<<'\n';}
void exportCageObj(const RestCage&c,const Graph&g,const std::string&path){std::ofstream out(path);if(!out)throw std::runtime_error("cannot open cage diagnostic OBJ");out<<std::setprecision(17)<<"# Immutable UV cage; physical particles and constrained triangles\n";for(size_t i=0;i<c.uv().size();++i){auto p=g.particles[i].x;out<<"v "<<p.x<<' '<<p.y<<' '<<p.z<<'\n';}for(auto uv:c.uv())out<<"vt "<<uv.x<<' '<<uv.y<<'\n';for(auto t:c.triangles())out<<"f "<<t[0]+1<<'/'<<t[0]+1<<' '<<t[1]+1<<'/'<<t[1]+1<<' '<<t[2]+1<<'/'<<t[2]+1<<'\n';if(!out)throw std::runtime_error("cannot write cage diagnostic OBJ");}
void smallLoadDiagnostics(const std::string&prefix){for(unsigned seed:{42,99}){Recipe r;r.preset="corridor";r.seed=seed;r.density=.9;r.width=.0045;r.broken=0;auto l=generate(r);BuildOptions o;o.cohesive=true;o.massScale=.01;o.stiffness=1;o.strength=1.25;o.junctionTolerance=.005;auto g=buildGraph(l,o);const auto c=buildRestCage(g);reportDeformation(c,g,"rest",seed);if(!prefix.empty())exportCageObj(c,g,prefix+"-"+std::to_string(seed)+"-rest.obj");g.settings.substeps=16;g.settings.iterations=12;int target=-1;double distance=1e30;for(int p=0;p<int(g.particles.size());++p)if(g.particles[p].invMass>0&&length(g.particles[p].uv-V2{.5,.5})<distance){target=p;distance=length(g.particles[p].uv-V2{.5,.5});}for(int tick=0;tick<150;++tick)step(g,{},tick>=30?std::vector<Force>{{target,{.015,0,0}}}:std::vector<Force>{});reportDeformation(c,g,"gravity_plus_center_x0.015_ticks30to149",seed);if(!prefix.empty())exportCageObj(c,g,prefix+"-"+std::to_string(seed)+"-load.obj");double maxStretch=0;for(const auto&e:g.edges)if(e.active)maxStretch=std::max(maxStretch,length(g.particles[e.a].x-g.particles[e.b].x)/e.rest);std::cout<<"DIAGNOSTIC small_load_target="<<target<<" seed="<<seed<<" max_active_stretch="<<maxStretch<<'\n';}}
void corridor(){for(unsigned seed:{42,99}){Recipe r;r.preset="corridor";r.seed=seed;r.density=.9;r.width=.0045;r.broken=0;r.quality=20;auto l=generate(r);BuildOptions o;o.cohesive=true;auto g=buildGraph(l,o);auto c=buildRestCage(g);topology(c,g);constrainedQuality(c);check(c.triangles()==buildRestCage(g).triangles(),"actual cage deterministic");double maxApprox=0,maxPreserved=0;for(int y=0;y<=60;++y)for(int x=0;x<=60;++x){V2 uv{x/60.,y/60.};auto plain=bindCageUV(c,uv),curved=bindPatchUV(c,l.patches[0],uv);check(plain&&curved,"actual patch square covered");maxApprox=std::max(maxApprox,length(evaluateCage(c,*plain,g)-l.patches[0].sample(uv)));maxPreserved=std::max(maxPreserved,length(evaluateCage(c,*curved,g)-l.patches[0].sample(uv)));}check(maxPreserved<1e-10,"analytic carrier rest shape preserved");check(c.triangles().size()<=8400&&c.triangles().size()*3<=25200,"hard mesh budgets");std::cout<<"PASS cage seed="<<seed<<" particles="<<g.particles.size()<<" triangles="<<c.triangles().size()<<" constraints="<<c.constraints().size()<<" max_plain_rest_error="<<maxApprox<<" max_offset_rest_error="<<maxPreserved<<'\n';}}
}
int main(int argc,char**argv){try{if(argc>1&&std::string(argv[1])=="--diagnostics"){smallLoadDiagnostics(argc>2?argv[2]:"");return 0;}affineAndRigid();edgeContinuityAndOwnership();curvedEdgeContinuity();collinearAndErrors();invalidInputs();nearBoundaryHull();gridConstraintCavity();cocircularGrid();enclosedCavityNode();skinnyOffsetFrame();corridor();std::cout<<"PASS UV cage contracts\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
